#include <bits/stdc++.h>
using namespace std;using State=uint64_t;static constexpr int N=5,Q=3,ROWS=243,RBITS=8;static uint16_t addrow[Q][ROWS][ROWS];static uint8_t dig[ROWS][N];static int p3[N+1];
inline uint16_t gr(State s,int i){return (s>>(RBITS*i))&255u;}inline State sr(State s,int i,uint16_t r){State mask=State(255)<<(RBITS*i);return(s&~mask)|(State(r)<<(RBITS*i));}inline State gate(State s,int a,int b,int l){return sr(s,b,addrow[l][gr(s,b)][gr(s,a)]);}State ident(){State s=0;for(int i=0;i<N;i++)s|=State(p3[i])<<(RBITS*i);return s;}
uint16_t lincomb(uint16_t coeff,const array<uint16_t,N>& rows){uint16_t out=0;for(int k=0;k<N;k++){int c=dig[coeff][k];if(c)out=addrow[c][out][rows[k]];}return out;}
State mul(State A,State B){array<uint16_t,N> br;for(int k=0;k<N;k++)br[k]=gr(B,k);State C=0;for(int i=0;i<N;i++)C|=State(lincomb(gr(A,i),br))<<(RBITS*i);return C;}
State inv(State A){int L[N][N],R[N][N]{};for(int i=0;i<N;i++){for(int j=0;j<N;j++)L[i][j]=dig[gr(A,i)][j];R[i][i]=1;}for(int c=0;c<N;c++){int p=c;while(p<N&&!L[p][c])p++;if(p==N)abort();if(p!=c){for(int j=0;j<N;j++){swap(L[p][j],L[c][j]);swap(R[p][j],R[c][j]);}}int iv=L[c][c]==1?1:2;for(int j=0;j<N;j++){L[c][j]=L[c][j]*iv%Q;R[c][j]=R[c][j]*iv%Q;}for(int i=0;i<N;i++)if(i!=c&&L[i][c]){int l=(Q-L[i][c])%Q;for(int j=0;j<N;j++){L[i][j]=(L[i][j]+l*L[c][j])%Q;R[i][j]=(R[i][j]+l*R[c][j])%Q;}}}State B=0;for(int i=0;i<N;i++){int r=0;for(int j=0;j<N;j++)r+=R[i][j]*p3[j];B|=State(r)<<(RBITS*i);}return B;}
uint16_t getcol(State A,int j){int c=0;for(int i=0;i<N;i++)c+=dig[gr(A,i)][j]*p3[i];return c;}
State coskey(State A){uint16_t can[N]{};int piv[N]{};State key=0;for(int j=N-1;j>=0;j--){uint16_t x=getcol(A,j);for(int k=N-1;k>j;k--){int coeff=dig[x][piv[k]],pv=dig[can[k]][piv[k]];if(coeff){int ratio=coeff*(pv==1?1:2)%Q;int l=(Q-ratio)%Q;x=addrow[l][x][can[k]];}}int p=-1;for(int i=N-1;i>=0;i--)if(dig[x][i]){p=i;break;}if(p<0)abort();can[j]=x;piv[j]=p;key|=State(x)<<(RBITS*j);}return key;}
bool isU(State A){for(int i=0;i<N;i++){auto r=gr(A,i);if(dig[r][i]!=1)return false;for(int j=i+1;j<N;j++)if(dig[r][j])return false;}return true;}int encU(State A){int c=0,m=1;for(int i=0;i<N;i++)for(int j=0;j<i;j++){c+=dig[gr(A,i)][j]*m;m*=Q;}return c;}
using Map=unordered_map<State,uint8_t>;
Map ball(int radius,const vector<array<int,3>>&gens){State I=ident();Map d;d.reserve(radius==4?500000:30000);d.max_load_factor(.7);vector<State>f{I};d[I]=0;for(int dep=0;dep<radius;dep++){vector<State>nx;nx.reserve(f.size()*8);for(State x:f)for(auto g:gens){State y=gate(x,g[0],g[1],g[2]);if(!d.count(y)){d[y]=dep+1;nx.push_back(y);}}f.swap(nx);cerr<<"ball r "<<radius<<" depth "<<dep+1<<" size "<<d.size()<<"\n";}return d;}
int main(){p3[0]=1;for(int i=1;i<=N;i++)p3[i]=p3[i-1]*Q;for(int x=0;x<ROWS;x++){int y=x;for(int j=0;j<N;j++){dig[x][j]=y%Q;y/=Q;}}for(int l=0;l<Q;l++)for(int a=0;a<ROWS;a++)for(int b=0;b<ROWS;b++){int c=0;for(int j=0;j<N;j++)c+=((dig[a][j]+l*dig[b][j])%Q)*p3[j];addrow[l][a][b]=c;}
 vector<array<int,3>> low,all;for(int s=0;s<N;s++)for(int t=0;t<N;t++)if(s!=t)for(int l=1;l<Q;l++){all.push_back({s,t,l});if(s<t)low.push_back({s,t,l});}
 // restricted BFS
 int usize=59049;vector<uint8_t> ld(usize,255);queue<State>q;State I=ident();q.push(I);ld[0]=0;int diam=0;while(!q.empty()){State x=q.front();q.pop();int dx=ld[encU(x)];diam=max(diam,dx);for(auto g:low){State y=gate(x,g[0],g[1],g[2]);int c=encU(y);if(ld[c]==255){ld[c]=dx+1;q.push(y);}}}cerr<<"restricted diameter "<<diam<<"\n";
 auto b3=ball(3,all),b4=ball(4,all);
 struct It{State x;uint8_t d;};unordered_map<State,vector<It>> A,B;A.reserve(50000);B.reserve(50000);for(auto&kv:b4)A[coskey(kv.first)].push_back({kv.first,kv.second});for(auto&kv:b3)B[coskey(kv.first)].push_back({kv.first,kv.second});
 vector<uint8_t> ad(usize,255);long long pairs=0;for(auto&kv:B){auto it=A.find(kv.first);if(it==A.end())continue;auto&vb=kv.second;auto&va=it->second;State r=va[0].x,ri=inv(r);struct U{State u,ui;uint8_t d;};vector<U> ua,ub;ua.reserve(va.size());ub.reserve(vb.size());for(auto&x:va){State u=mul(ri,x.x);if(!isU(u)){cerr<<"bad A\n";return 2;}ua.push_back({u,inv(u),x.d});}for(auto&x:vb){State u=mul(ri,x.x);if(!isU(u)){cerr<<"bad B\n";return 3;}ub.push_back({u,inv(u),x.d});}pairs+=(long long)ua.size()*ub.size();for(auto&bb:ub)for(auto&aa:ua){State t=mul(bb.ui,aa.u);int c=encU(t);ad[c]=min<int>(ad[c],bb.d+aa.d);}}
 int miss=0,def=0;map<pair<int,int>,int>ct;for(int c=0;c<usize;c++){if(ad[c]==255)miss++;else{ct[{ld[c],ad[c]}]++;if(ad[c]<ld[c])def++;}}
 cout<<"q 3 n 5 restricted_diameter "<<diam<<" ball3 "<<b3.size()<<" ball4 "<<b4.size()<<" coset_pairs "<<pairs<<" missing "<<miss<<" defects "<<def<<"\n";for(auto&x:ct)cout<<"low "<<x.first.first<<" amb "<<x.first.second<<" count "<<x.second<<"\n";
}
